function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'WordFilter' || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Start with WordFilter and a list of words.';
  const words = args[0][0];
  const lower = /^[a-z]{1,7}$/;
  if (words.length < 1 || words.length > 10000) return 'words needs 1 to 10^4 entries.';
  if (words.some(word => typeof word !== 'string' || !lower.test(word))) return 'Each word has 1 to 7 lowercase letters.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to f.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'f') return 'Only f can follow the constructor.';
    if (args[i].length !== 2 || args[i].some(part => typeof part !== 'string' || !lower.test(part))) return 'pref and suff each have 1 to 7 lowercase letters.';
  }
  return null;
}

