class WordFilter {
  constructor(words) {
    this.root = { children: new Map(), weight: -1 };
    for (let index = 0; index < words.length; index++) {
      const word = words[index];
      for (let cut = word.length; cut >= 0; cut--) {
        const key = word.slice(cut) + '{' + word;
        let node = this.root;
        for (const ch of key) {
          if (!node.children.has(ch)) {
            node.children.set(ch, { children: new Map(), weight: -1 });
          }
          node = node.children.get(ch);
          node.weight = index;
        }
      }
    }
  }

  f(pref, suff) {
    let node = this.root;
    for (const ch of suff + '{' + pref) {
      node = node.children.get(ch);
      if (node === undefined) {
        return -1;
      }
    }
    return node.weight;
  }
}

