class WordFilter {
  constructor(words) {
    this.words = words.slice();
  }
  f(pref, suff) {
    let found = -1;
    this.words.forEach((word, i) => {
      if (word.length >= pref.length && word.length >= suff.length && word.slice(0, pref.length) === pref && word.slice(word.length - suff.length) === suff) found = i;
    });
    return found;
  }
}

