function generate(rand, size) {
  const large = size === 'large';
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, large ? 2 + Math.floor(rand() * 4) : 2 + Math.floor(rand() * 2));
  const maxLength = large ? 7 : 1 + Math.floor(rand() * 4);
  const text = (length) => Array.from({ length }, () => alphabet[Math.floor(rand() * alphabet.length)]).join('');
  const count = large ? 2000 : 1 + Math.floor(rand() * 6);
  const words = Array.from({ length: count }, () => text(1 + Math.floor(rand() * maxLength)));
  const operations = ['WordFilter'];
  const args = [[words]];
  const calls = large ? 499 : 1 + Math.floor(rand() * 10);
  for (let i = 0; i < calls; i++) {
    const a = words[Math.floor(rand() * words.length)];
    const b = rand() < 0.6 ? a : words[Math.floor(rand() * words.length)];
    const pref = rand() < 0.85 ? a.slice(0, 1 + Math.floor(rand() * a.length)) : text(1 + Math.floor(rand() * 7));
    const suff = rand() < 0.85 ? b.slice(Math.floor(rand() * b.length)) : text(1 + Math.floor(rand() * 7));
    operations.push('f');
    args.push([pref, suff]);
  }
  return [operations, args];
}
